parameters.jsCode:
const body = $input.first().json.body;
const value = body?.entry?.[0]?.changes?.[0]?.value ?? {};
const msg = value.messages?.[0] ?? {};
const metadata = value.metadata ?? {};

// Texto normal O respuesta de un botón/lista interactiva.
let userMessage = msg.text?.body ?? '';
if (msg.type === 'interactive') {
  const inter = msg.interactive ?? {};
  // El id que definimos en el menú (ej. 'ventas_mes') llega aquí; lo usamos como texto
  userMessage = inter.button_reply?.id || inter.list_reply?.id
             || inter.button_reply?.title || inter.list_reply?.title || '';
}

return [{ json: {
  from: msg.from ?? null,
  phone_number_id: metadata.phone_number_id ?? null,
  user_message: userMessage,
  message_id: msg.id ?? null,
  timestamp: msg.timestamp ?? null
}}];

const empresaRow = $input.first().json;
const extra = $('Extraer campos').first().json;
return [{ json: {
  empresa: empresaRow.empresa ?? null,
  nombre_empresa: empresaRow.nombre_empresa ?? 'la empresa',
  nombre_asistente: empresaRow.nombre_asistente ?? 'Asistente',
  from: extra.from,
  phone_number_id: extra.phone_number_id,
  user_message: extra.user_message,
  message_id: extra.message_id
}}];

const prev = $('Merge empresa+msg').first().json;
const rolRows = $input.all();
const rolRow = rolRows.length > 0 ? rolRows[0].json : {};
return [{ json: {
  ...prev,
  rol: rolRow.rol ?? 'anon',
  rut_cliente: rolRow.rut_cliente ?? null,
  nombre_contacto: rolRow.nombre ?? null
}}];

const ctx = $('Determinar rol').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.role && r.content).reverse();
const history = rows.map(r => ({ role: r.role, content: r.content }));
const historyText = history.map(h => h.role + ': ' + h.content).join('\n');
return [{ json: {
  empresa: ctx.empresa,
  nombre_empresa: ctx.nombre_empresa,
  nombre_asistente: ctx.nombre_asistente,
  rol: ctx.rol,
  rut_cliente: ctx.rut_cliente,
  from: ctx.from,
  phone_number_id: ctx.phone_number_id,
  user_message: ctx.user_message,
  message_id: ctx.message_id,
  history,
  history_text: historyText || '(sin historial previo)'
}}];

